SELECT DATE_TRUNC('WEEK', sale_date) AS week_start, CASE WHEN revenue >= 3700 THEN 'PREMIUM' ELSE 'STANDARD' END AS revenue_tier, AVG(units) AS avg_units, CORR(units, revenue) AS corr_units_revenue, ROUND(AVG(units), 2) AS avg_units_2, COUNT(*) AS cnt, PERCENTILE_APPROX(revenue, 0.95) AS revenue_p95, COUNT(DISTINCT id) AS distinct_ids FROM store_sales GROUP BY DATE_TRUNC('WEEK', sale_date), CASE WHEN revenue >= 3700 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING CORR(units, revenue) >= 0 ORDER BY avg_units DESC NULLS FIRST;
